'use strict';
const $ = s => document.querySelector(s);
const escapeHTML = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STORE='duolingo-codex-business-v1';
const localDay=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const blank=()=>({version:1,xp:0,completed:{},mistakes:[],days:{},history:[],strand:'finance',goal:30,sound:true});
let state=blank(),storageOK=true;
try{const raw=JSON.parse(localStorage.getItem(STORE));if(raw?.version===1&&typeof raw.completed==='object'&&raw.completed!==null&&Array.isArray(raw.mistakes)&&raw.days&&Array.isArray(raw.history)){state={...blank(),...raw};if(!STRANDS.some(s=>s.id===state.strand))state.strand='finance';}}catch(e){storageOK=false;}
function save(){try{localStorage.setItem(STORE,JSON.stringify(state));}catch(e){storageOK=false;toast('Progress could not be saved. Check your browser storage settings.');}}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
function streak(){let n=0,d=new Date();if(!state.days[localDay(d)])d.setDate(d.getDate()-1);while(state.days[localDay(d)]){n++;d.setDate(d.getDate()-1);}return n;}
function todayXP(){return state.days[localDay()]?.xp||0;}
function totalDone(){return Object.values(state.completed).filter(x=>x.passed).length;}
function updateHeader(){ $('#xp').textContent=state.xp;$('#streak').textContent=streak();$('#profile-btn').textContent='Lv '+(Math.floor(state.xp/150)+1);$('#profile-btn').title='Level '+(Math.floor(state.xp/150)+1)+' · '+(150-state.xp%150)+' XP to your next level'; }
function fox(){return `<svg class="fox-hero" viewBox="0 0 260 260" aria-label="Finn, your friendly business fox" role="img"><ellipse cx="140" cy="246" rx="99" ry="12" fill="#cad9b8"/><path d="M190 166Q258 131 244 211Q233 247 186 230" fill="#df8747"/><path d="M237 174Q256 218 221 236L218 205Z" fill="#fff2da"/><path d="M79 177Q126 142 180 181L198 245H66Z" fill="#087f68"/><path d="M100 185L128 212L153 183L141 247H115Z" fill="#f9f6e9"/><path d="M126 212L137 220L132 242L121 242L119 220Z" fill="#b3d75f"/><path d="M66 106L49 33Q48 23 62 29L108 67M158 67L202 29Q216 19 210 38L195 113" fill="#e78b47" stroke="#b76d38" stroke-width="3" stroke-linejoin="round"/><path d="M61 41L70 92L94 73ZM197 42L170 76L195 95Z" fill="#6b4937"/><path d="M61 108Q55 57 127 58Q202 56 204 113L188 152Q168 180 128 184Q86 180 65 151L48 119Z" fill="#ed9852"/><path d="M54 119Q88 107 128 148Q165 108 202 118Q188 171 128 184Q75 174 54 119Z" fill="#fff6df"/><ellipse cx="93" cy="112" rx="7" ry="10" fill="#263d32"/><ellipse cx="163" cy="112" rx="7" ry="10" fill="#263d32"/><circle cx="95" cy="108" r="2" fill="#fff"/><circle cx="165" cy="108" r="2" fill="#fff"/><path d="M118 143Q128 137 139 143L129 153Z" fill="#314536"/><path d="M115 158Q128 169 142 157" fill="none" stroke="#314536" stroke-width="3" stroke-linecap="round"/><ellipse cx="79" cy="135" rx="11" ry="6" fill="#dc7e43"/><ellipse cx="177" cy="135" rx="11" ry="6" fill="#dc7e43"/><path d="M76 200L47 223L83 239" fill="none" stroke="#087f68" stroke-width="24" stroke-linecap="round"/><rect x="49" y="210" width="64" height="43" rx="5" fill="#b9d88d" stroke="#729d59" stroke-width="2" transform="rotate(-12 80 230)"/><path d="M61 236L71 227L80 231L96 217" fill="none" stroke="#4c7e45" stroke-width="4"/><path d="M178 198L194 215" fill="none" stroke="#087f68" stroke-width="24" stroke-linecap="round"/><ellipse cx="194" cy="218" rx="14" ry="11" fill="#ed9852"/></svg>`;}
function intro(kicker,title,subtitle,pill='🇮🇪 Junior Cycle · 3rd year'){return `<div class="intro"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${subtitle}</p></div>${pill?`<div class="level-pill">${pill}</div>`:''}</div>`;}
function week(){const now=new Date(),monday=new Date();monday.setDate(now.getDate()-((now.getDay()+6)%7));return ['M','T','W','T','F','S','S'].map((label,i)=>{let d=new Date(monday);d.setDate(monday.getDate()+i);const day=localDay(d),done=!!state.days[day];return `<div class="day ${done?'studied':''} ${day===localDay()?'today':''}" title="${day}${done?' · studied':''}">${label}<span>${done?'✓':'·'}</span></div>`;}).join('');}
function rail(){const pct=Math.min(100,todayXP()/state.goal*100);return `<div class="right-rail"><section class="card"><div class="card-title"><h3>Your daily goal</h3><button class="text-button" id="goal-btn">Edit</button></div><p class="card-sub">A little progress, every day.</p><div class="goal-graphic"><div class="goal-ring" style="--value:${pct*3.6}deg"><div>⚡</div></div><div><strong>${todayXP()} <span style="font-size:13px;color:#9aa88f">/ ${state.goal} XP</span></strong><p>${pct>=100?'Goal reached. Nice work!':'You’ve got this. Keep going!'}</p></div></div><div class="goal-bar"><span style="width:${pct}%"></span></div><div class="goal-text"><span>${pct>=100?'Daily goal complete':'Today’s learning'}</span><strong>${Math.round(pct)}%</strong></div><div class="week">${week()}</div></section><section class="card challenge"><span class="mini-tag">THE DAILY CHALLENGE</span><span class="challenge-spark">✦</span><h3>Big brain.<br>Small challenge.</h3><p>Five questions. Three strands.<br>Put your business brain to work.</p><button class="secondary" id="daily-btn">Take the challenge <span>→</span></button></section><section class="tip"><span>💡</span><div><h4>Finn’s study tip</h4><p>Explain your answer out loud. If you can teach it, you’re learning it.</p></div></section></div>`;}
function renderLearn(){let strand=STRANDS.find(s=>s.id===state.strand),lessons=LESSONS.filter(l=>l.strand===strand.id),next=lessons.find(l=>!state.completed[l.id]?.passed)||lessons[0],done=lessons.filter(l=>state.completed[l.id]?.passed).length;$('#main').innerHTML=intro('YOUR NEXT SMALL WIN','A little learning. A lot of possibility.','Build your business brain, one small lesson at a time.')+`<div class="columns"><div><section class="hero"><div class="hero-copy"><span class="mini-tag">${totalDone()?'WELCOME BACK, FUTURE FOUNDER':'LET’S GET STARTED, FUTURE FOUNDER'}</span><h2>Real life skills.<br>One lesson away.</h2><p>From your first budget to your big idea. Make business your thing.</p><button class="primary" id="continue-btn">${totalDone()?'Continue learning':'Start learning'} <span>→</span></button></div>${fox()}<span class="floating-coin" aria-hidden="true">€</span></section><div class="section-title"><h2>Your learning path</h2><small>24 lessons · 3 strands</small></div><div class="tabs" role="tablist" aria-label="Course strands">${STRANDS.map(s=>`<button class="tab ${s.id===strand.id?'active':''}" role="tab" aria-selected="${s.id===strand.id}" data-strand="${s.id}">${s.icon} &nbsp;${s.name}</button>`).join('')}</div><div class="unit-banner"><span class="unit-icon">${strand.icon}</span><div><h3>${strand.name}</h3><p>${strand.description}</p></div><span class="unit-count">${done} / 8 complete</span></div><div class="path">${lessons.map((l,i)=>{const passed=state.completed[l.id]?.passed,current=l.id===next.id;return `<article class="lesson-row ${passed?'done':''} ${current?'current':''}"><span class="lesson-node" aria-hidden="true">${passed?'✓':l.icon}</span><div class="lesson-info"><h4>${l.title}</h4><p>Lesson ${i+1} · ${i===7?'Applied challenge':'4 quick questions'} · ~4 min</p>${current&&!passed?'<span class="tiny">UP NEXT · YOU CAN DO THIS</span>':''}</div><button class="row-btn" data-lesson="${l.id}" aria-label="${passed?'Review':'Start'} ${l.title}">${passed?'REVIEW':current?'START →':'EXPLORE'}</button></article>`;}).join('')}</div></div>${rail()}</div>`;$('#continue-btn').onclick=()=>startLesson(next.id);document.querySelectorAll('[data-strand]').forEach(b=>b.onclick=()=>{state.strand=b.dataset.strand;save();render();});bindLessons();$('#daily-btn').onclick=startDaily;$('#goal-btn').onclick=goalDialog;}
function bindLessons(){document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>startLesson(b.dataset.lesson));}
const allQuestions=()=>LESSONS.flatMap(l=>l.questions.map(q=>({...q,lessonId:l.id})));
function shuffled(items,random=Math.random){const result=[...items];for(let i=result.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[result[i],result[j]]=[result[j],result[i]];}return result;}
function randomiseAnswers(questions){return questions.map(q=>{const order=shuffled(q.options.map((text,i)=>({text,correct:i===q.answer})));return {...q,options:order.map(o=>o.text),answer:order.findIndex(o=>o.correct)};});}
function dailyQuestions(day=localDay()){let hash=[...day].reduce((n,c)=>n*31+c.charCodeAt(0),7)>>>0;const random=()=>{hash=(Math.imul(hash,1664525)+1013904223)>>>0;return hash/4294967296;};return shuffled(STRANDS.flatMap((strand,i)=>shuffled(allQuestions().filter(q=>LESSONS.find(l=>l.id===q.lessonId).strand===strand.id),random).slice(0,i===2?1:2)),random);}
function startDaily(){startSession('Your daily challenge',dailyQuestions(),'daily');}
function renderPractice(){const count=state.mistakes.length;$('#main').innerHTML=intro('A LITTLE PRACTICE GOES A LONG WAY','Make it stick.','Revisit the tricky bits, connect ideas, and grow your confidence.')+arcadeMarkup()+`<div class="practice-grid"><section class="card practice-card"><span class="big-icon">↻</span><span class="eyebrow">PERSONALISED FOR YOU</span><h3>Learn from your mistakes</h3><p>${count?`${count} question${count!==1?'s':''} to revisit. Turn an “almost” into an “I’ve got this”.`:'Your mistake list is clear. Any questions you miss in a lesson will appear here.'}</p><button class="primary" id="mistakes-btn" ${!count?'disabled':''}>Review ${count} question${count!==1?'s':''} →</button></section><section class="card practice-card challenge"><span class="big-icon">ϟ</span><span class="eyebrow">MIX IT UP</span><h3>The daily five</h3><p>A fresh mix each day, drawn from all three strands. Small challenge, useful connections.</p><button class="primary" id="daily-btn">Take today’s challenge →</button></section><section class="card practice-card"><span class="big-icon">⚑</span><span class="eyebrow">READY FOR A CHALLENGE?</span><h3>Revision sprint</h3><p>Twelve questions, balanced across the three strands. Take your time and explain the answers.</p><button class="primary" id="sprint-btn">Start revision sprint →</button></section></div><section class="card"><div class="eyebrow">THINK · CALCULATE · RECOMMEND</div><h2>Your exam-answer toolkit</h2><p class="card-sub">Use a clear method when tackling an applied Business Studies question.</p><div class="teach-note"><p><strong>1. Spot the task.</strong> Are you asked to calculate, explain, compare or evaluate?<br><strong>2. Show your working.</strong> Write the formula, substitute the figures and include units.<br><strong>3. Use the context.</strong> Connect your explanation to the person or business in the question.<br><strong>4. Make a judgement.</strong> If asked, recommend an action and give a supported reason.</p></div><p class="card-sub">These are original revision activities, not official examination questions.</p></section>`;bindArcade();$('#mistakes-btn').onclick=()=>startSession('Turn mistakes into progress',shuffled(allQuestions().filter(q=>state.mistakes.includes(q.id))).slice(0,12),'review');$('#daily-btn').onclick=startDaily;$('#sprint-btn').onclick=()=>startSession('Your revision sprint',shuffled(STRANDS.flatMap(s=>shuffled(allQuestions().filter(q=>LESSONS.find(l=>l.id===q.lessonId).strand===s.id)).slice(0,4))),'sprint');}
function renderNotes(){const search=sessionStorage.getItem('business-notes-search')||'';$('#main').innerHTML=intro('YOUR POCKET-SIZED STUDY GUIDE','Good notes. Clear thinking.','Key ideas, worked examples, and the “why” behind your answers.')+`<div class="note-toolbar"><input id="note-search" aria-label="Search study notes" placeholder="Search budgets, marketing, inflation…" type="search" value="${escapeHTML(search)}"></div><div class="note-grid" id="note-results"></div>`;function results(){const query=$('#note-search').value.toLowerCase().trim(),found=LESSONS.filter(l=>(l.title+' '+l.notes+' '+STRANDS.find(s=>s.id===l.strand).name).toLowerCase().includes(query));$('#note-results').innerHTML=found.length?found.map(l=>`<article class="card note-card"><span class="strand-tag">${STRANDS.find(s=>s.id===l.strand).name} · ${l.outcomes}</span><h3>${l.icon} &nbsp;${l.title}</h3><p>${l.summary}</p><button class="secondary" data-lesson="${l.id}">Read & practise →</button></article>`).join(''):'<div class="empty"><h3>No notes found</h3><p>Try a topic such as cash, tax, trade or research.</p></div>';bindLessons();}$('#note-search').oninput=()=>{sessionStorage.setItem('business-notes-search',$('#note-search').value);results();};results();}
function renderProgress(){const done=totalDone(),perfect=Object.values(state.completed).filter(x=>x.best===100).length,badges=[['🌱','First small win','Complete your first lesson',done>=1],['💶','Money minded','Complete all Personal Finance lessons',LESSONS.filter(l=>l.strand==='finance').every(l=>state.completed[l.id]?.passed)],['🚀','Idea into action','Complete all Enterprise lessons',LESSONS.filter(l=>l.strand==='enterprise').every(l=>state.completed[l.id]?.passed)],['🌍','Big picture thinker','Complete all Our Economy lessons',LESSONS.filter(l=>l.strand==='economy').every(l=>state.completed[l.id]?.passed)],['✦','A perfect little win','Get every answer right in one lesson',perfect>0],['🔥','A growing habit','Study on three consecutive days',streak()>=3]];$('#main').innerHTML=intro('LOOK HOW FAR YOU’VE COME','Small wins add up.','Your effort, your pace, your progress.')+`<div class="stats-grid">${[['✦',state.xp,'Total XP'],['✓',done+' / 24','Lessons complete'],['🔥',streak(),'Day streak'],['◎',Math.round(done/24*100)+'%','Course completed']].map(([i,n,t])=>`<section class="card stat-card">${i}<strong>${n}</strong><small>${t}</small></section>`).join('')}</div><section class="card"><h2>Your three strands</h2><p class="card-sub" style="margin-bottom:22px">Score at least 75% in a lesson to complete it. You can retry as often as you like.</p>${STRANDS.map(s=>{let n=LESSONS.filter(l=>l.strand===s.id&&state.completed[l.id]?.passed).length;return `<div class="progress-strand"><div class="card-title"><h3>${s.icon} &nbsp; ${s.name}</h3><span class="card-sub">${n} / 8 lessons</span></div><div class="progress-track"><span style="width:${n/8*100}%"></span></div></div>`;}).join('')}</section><div class="section-title"><h2>Milestones worth celebrating</h2><small>${badges.filter(b=>b[3]).length} of 6 earned</small></div><div class="badge-grid">${badges.map(b=>`<section class="card ${b[3]?'':'unearned'}"><span class="badge-icon">${b[0]}</span><h3>${b[1]}</h3><p>${b[2]}${b[3]?' · Earned ✓':''}</p></section>`).join('')}</div><section class="card"><h2>Recent learning</h2>${state.history.length?state.history.slice(0,8).map(h=>`<div class="recent-row"><div><strong>${escapeHTML(h.title)}</strong><br><small>${escapeHTML(h.date)} · ${h.score}% correct</small></div><span class="subtle-link">+${h.xp} XP</span></div>`).join(''):'<p class="card-sub">Your first completed session will appear here. Every small start counts.</p>'}</section>`;}
function render(){const page=['learn','practice','notes','progress'].includes(location.hash.slice(1))?location.hash.slice(1):'learn';document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===page);if(a.dataset.nav===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#page-name').textContent=({learn:'Learn',practice:'Practice',notes:'Study notes',progress:'My progress'})[page];({learn:renderLearn,practice:renderPractice,notes:renderNotes,progress:renderProgress})[page]();if(!storageOK)$('#main').insertAdjacentHTML('afterbegin','<p class="warning">Browser storage is unavailable. Your progress may not be saved after closing this page.</p>');updateHeader();}
let session=null;
function startLesson(id){const l=LESSONS.find(l=>l.id===id);session={title:l.title,lesson:l,questions:randomiseAnswers(l.questions),index:0,correct:0,selected:null,checked:false,type:'lesson',phase:'teach',startedAt:Date.now()};initialiseGame(session);showSession();$('#lesson-dialog').showModal();}
function startSession(title,questions,type){if(!questions.length){toast('Nothing to review yet. Try a lesson first.');return;}session={title,questions:randomiseAnswers(questions),index:0,correct:0,selected:null,checked:false,type,phase:'question',startedAt:Date.now()};initialiseGame(session);showSession();$('#lesson-dialog').showModal();}
function closeSession(){pauseTimer();if(!session||session.phase==='done'||session.phase==='teach'||session.phase==='ready'){session=null;$('#lesson-dialog').close();return;}if(session.phase==='exit')return;session.phaseBeforeExit=session.phase;session.phase='exit';showSession();}
$('#lesson-dialog').addEventListener('cancel',e=>{e.preventDefault();closeSession();});
function showSession(){const d=$('#lesson-dialog'),s=session;let body='',foot='',progress=s.phase==='teach'||s.phase==='ready'?0:s.phase==='done'?100:s.type==='match'?s.matched.length/4*100:(s.index+(s.checked?1:0))/s.questions.length*100;
if(s.phase==='exit'){body=`<div class="lesson-body">${coach('Your next small win will be here when you’re ready.')}<h2>Leave this mission?</h2><p>Your previously saved progress is safe. This unfinished mission won’t earn XP.</p></div>`;foot=`<button class="secondary" id="leave-btn">Leave mission</button><button class="primary" id="resume-btn">Keep playing →</button>`;}
else if(s.phase==='ready'){body=`<div class="lesson-body result"><span class="result-icon">⚡</span><div class="eyebrow">BUSINESS BLITZ</div><h2>You vs. the clock.</h2><p>12 questions. 60 seconds of answer time.<br>The timer pauses after each answer so you can learn.<br>No lesson progress to lose. Just give it a go!</p>${coach('Ready, steady… business!')}</div>`;foot='<span>One good answer at a time.</span><button class="primary" id="begin-blitz">Let’s go! →</button>';}
else if(s.phase==='recharge'){body=`<div class="lesson-body result"><span class="result-icon">💚</span><div class="eyebrow">A LITTLE HEART REFILL</div><h2>New hearts. Same brilliant you.</h2>${coach('Mistakes are how brains level up. Let’s recharge and keep going.')}<div class="teach-note"><p>${s.lesson?s.lesson.summary:'Read the explanation, take a breath and try the next question. You’re here to learn.'}</p></div></div>`;foot='<span>Always free. Never a waiting timer.</span><button class="primary" id="refill-btn">Refill & keep going ♥</button>';}
else if(s.phase==='teach'){const l=s.lesson;body=`<div class="lesson-body"><div class="eyebrow">MISSION ${LESSONS.filter(x=>x.strand===l.strand).indexOf(l)+1} · ${STRANDS.find(x=>x.id===l.strand).name}</div><h2>${l.icon} &nbsp;${l.title}</h2>${coach(l.summary)}<div class="teach-note"><h3>Your secret weapon</h3><p>${l.notes}</p></div><div class="worked"><strong>LET’S MAKE IT REAL</strong><p>${l.example}</p></div><p class="outcome-label">Junior Cycle learning outcomes: ${l.outcomes}</p></div>`;foot='<span>4 challenges · 3 hearts · you’ve got this.</span><button class="primary" id="begin-btn">Mission accepted →</button>';}
else if(s.phase==='match'){body=matchMarkup(s);foot=`<span>${s.matched.length?`${s.matched.length} connections made. Keep it up!`:'Pick one tile from each column.'}</span><span class="combo-meter">✦ +${s.matched.length*5} XP in reach</span>`;}
else if(s.phase==='question'){const q=s.questions[s.index],numeric=numericAnswer(q)!==null,right=s.selected===q.answer,short=q.options.every(o=>o.length<35),response=s.checked?(right?(s.combo>=3?`${s.combo} in a row! Your business brain is on fire!`:'Brilliant! That’s a smart business move.'):'Almost! This is where the learning happens.'):(numeric?'Number ninja time. Show me your answer.':s.index===0?'Let’s put your business brain to work!':s.combo>=2?`${s.combo} in a row. Can you keep it going?`:'New challenge. Fresh chance to shine.');body=`<div class="lesson-body"><div class="challenge-meta"><span class="eyebrow">${numeric?'NUMBER NINJA':short?'PICK YOUR MOVE':'BUSINESS BRAIN CHALLENGE'}</span>${s.combo>=2?`<span class="combo-meter">🔥 ${s.combo} COMBO</span>`:''}</div>${coach(response,s.checked?(right?'cheer':'thinking'):'happy')}<h2>${q.prompt}</h2>${numeric?`<div class="number-answer ${s.checked?(right?'right':'wrong'):''}"><label for="number-input">Your answer${q.options[q.answer].includes('€')?' (€)':q.options[q.answer].includes('%')?' (%)':''}</label><input type="text" inputmode="decimal" autocomplete="off" id="number-input" value="${escapeHTML(s.typed||'')}" placeholder="Type your answer…" ${s.checked?'disabled':''}>${s.checked?`<span>${right?'✓ Nice calculation!':`Correct answer: ${q.options[q.answer]}`}</span>`:''}</div>`:`<div class="option-list ${short?'option-grid':''}" role="group" aria-label="Answer choices">${q.options.map((o,i)=>`<button class="option ${s.selected===i?'selected':''} ${s.checked&&i===q.answer?'correct':''} ${s.checked&&s.selected===i&&i!==q.answer?'wrong':''}" data-option="${i}" aria-pressed="${s.selected===i}" ${s.checked?'disabled':''}><span>${i+1}</span>${o}</button>`).join('')}</div>`}${s.checked?`<div class="feedback ${right?'':'wrong'}" role="status"><strong>${right?(s.combo>0&&s.combo%3===0?'🔥 Combo bonus! +5 XP':'✓ Nailed it!'):'Here’s your power-up for next time'}</strong><p>${q.explanation}</p></div>`:''}</div>`;foot=`<span>${s.checked?(right?'That’s a win. Take it.':'Mistakes make your brain stronger.'):'Tap, think, make your move.'}</span><button class="primary" id="check-btn" ${s.selected===null?'disabled':''}>${s.checked?(s.index===s.questions.length-1?'Claim my XP':'Continue'):'Check it'} →</button>`;}
else if(s.phase==='done'){const score=s.finalScore??Math.round(s.correct/s.questions.length*100),passed=score>=75,stars=score===100?3:score>=75?2:score>=50?1:0;body=`<div class="lesson-body result"><div class="reward-stars" aria-label="${stars} out of 3 stars">${[0,1,2].map(i=>`<span class="${i<stars?'earned':''}">★</span>`).join('')}</div><div class="eyebrow">${score===100?'FLAWLESS FINISH':passed?'MISSION COMPLETE':'A LITTLE STRONGER THAN BEFORE'}</div><h2>${score===100?'Business brain: activated!':passed?'You did the thing!':'Every try is a level-up.'}</h2>${coach(score===100?'A perfect run! I knew you had it in you.':passed?'That’s another small win in your pocket. Fancy one more?':'A few tricky ones? Good. Now we know what to practise.',passed?'cheer':'thinking')}<p>${s.type==='lesson'&&!passed?'Get 75% to complete this mission. Your missed questions are ready in Practice.':s.type==='match'?'Four connections made. Look at that business brain go!':s.type==='blitz'?'Time well spent. Ready to beat your own score?':'Real skills. Earned one smart answer at a time.'}</p><div class="result-stats"><div><strong>${score}%</strong><small>ACCURACY</small></div><div><strong>+${s.earned}</strong><small>XP EARNED</small></div><div><strong>${s.maxCombo||0} 🔥</strong><small>BEST COMBO</small></div></div>${s.bonus?`<p class="combo-summary">Includes +${s.bonus} combo XP${s.replay?' (repeat rewards reduced)':''}</p>`:''}</div>`;foot=`<button class="secondary" id="retry-btn">Play again ↻</button><button class="primary" id="finish-btn">Back to my adventure →</button>`;}
const isPlaying=['question','recharge'].includes(s.phase);d.innerHTML=`<div class="dialog-head"><button class="close-btn" id="close-lesson" aria-label="Close lesson">×</button><div class="progress-track" role="progressbar" aria-valuenow="${Math.round(progress)}" aria-valuemin="0" aria-valuemax="100" aria-label="Session progress"><span style="width:${progress}%"></span></div>${isPlaying?`<span class="hearts" aria-label="${s.hearts} of 3 hearts">${[0,1,2].map(i=>`<span class="${i<s.hearts?'full':'empty-heart'}">♥</span>`).join('')}</span>`:''}${s.type==='blitz'&&isPlaying?`<span class="timer-pill" id="timer-value" aria-label="Time remaining">${Math.ceil((s.remainingMs||0)/1000)}s</span>`:`<small>${s.phase==='teach'?'GET READY':s.phase==='done'?'YOU DID IT':s.type==='match'?s.matched.length+' / 4':`${s.index+1} / ${s.questions.length}`}</small>`}<button class="sound-btn" id="sound-btn" aria-label="${state.sound===false?'Turn sound on':'Turn sound off'}">${state.sound===false?'♫̸':'♫'}</button></div>${body}<div class="lesson-foot">${foot}</div>`;
$('#close-lesson').onclick=closeSession;$('#sound-btn').onclick=()=>{state.sound=state.sound===false;save();showSession();if(state.sound)playSound('correct');};
if(s.phase==='exit'){$('#leave-btn').onclick=()=>{session=null;d.close();render();};$('#resume-btn').onclick=()=>{s.phase=s.phaseBeforeExit;if(s.type==='match'&&s.mismatch){s.mismatch=false;s.picks={};}showSession();runTimer();};}
if(s.phase==='teach')$('#begin-btn').onclick=()=>{s.phase='question';showSession();};
if(s.phase==='ready')$('#begin-blitz').onclick=()=>{s.phase='question';showSession();runTimer();};
if(s.phase==='recharge')$('#refill-btn').onclick=()=>{s.hearts=3;s.phase='question';advanceQuestion();};
if(s.phase==='match')bindMatching();
if(s.phase==='question'){const q=s.questions[s.index];if(numericAnswer(q)!==null&&!s.checked){$('#number-input').oninput=e=>{s.typed=e.target.value;s.selected=s.typed.trim()===''?null:parseNumber(s.typed)===numericAnswer(q)?q.answer:-1;$('#check-btn').disabled=s.selected===null;};$('#number-input').onkeydown=e=>{if(e.key==='Enter'&&s.selected!==null)$('#check-btn').click();};}d.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>{s.selected=Number(b.dataset.option);showSession();d.querySelector(`[data-option="${s.selected}"]`).focus();});$('#check-btn').onclick=()=>{if(s.selected===null)return;if(!s.checked){pauseTimer();s.checked=true;recordAnswer(s,q,s.selected===q.answer);showSession();$('#check-btn').focus();}else if(s.index<s.questions.length-1){if(s.hearts===0){s.phase='recharge';showSession();}else advanceQuestion();}else finishSession();};}
if(s.phase==='done'){$('#finish-btn').onclick=()=>{session=null;d.close();render();};$('#retry-btn').onclick=()=>{const l=s.lesson,title=s.title,qs=s.questions,type=s.type;d.close();type==='match'?startMatching():l?startLesson(l.id):startSession(title,shuffled(qs),type);};}
d.scrollTop=0;}
function advanceQuestion(){const s=session;s.index++;s.selected=null;s.checked=false;s.typed='';showSession();const h=$('#lesson-dialog h2');h.setAttribute('tabindex','-1');h.focus();runTimer();}
function finishSession(){const s=session;if(s.phase==='done')return;pauseTimer();const score=s.type==='match'?Math.round(s.correct/s.attempts*100):Math.round(s.correct/s.questions.length*100);s.finalScore=score;const day=localDay(),replay=s.lesson?!!state.completed[s.lesson.id]?.attempts:s.type==='daily'?!!state.days[day]?.daily:['blitz','match'].includes(s.type)?!!state.days[day]?.[s.type]:false;s.replay=replay;s.bonus=s.bonus||0;s.earned=s.type==='match'?(replay?8:20)+(score===100&&!replay?5:0):s.correct*(replay?2:10)+(replay?Math.min(2,s.bonus):s.bonus);if(s.lesson){const previous=state.completed[s.lesson.id]||{};state.completed[s.lesson.id]={best:Math.max(score,previous.best||0),passed:!!previous.passed||score>=75,attempts:(previous.attempts||0)+1};}state.xp+=s.earned;state.days[day]=state.days[day]||{xp:0,sessions:0};state.days[day].xp+=s.earned;state.days[day].sessions++;if(['daily','blitz','match'].includes(s.type))state.days[day][s.type]=true;state.history.unshift({title:s.title,date:day,score,xp:s.earned});state.history=state.history.slice(0,100);save();s.phase='done';showSession();updateHeader();playSound(score>=75?'win':'correct');if(score>=75)confetti();}
function goalDialog(){$('#about-dialog').innerHTML=`<div class="dialog-head"><h3>A goal that fits your day</h3><button class="close-btn" style="margin-left:auto" id="close-about" aria-label="Close daily goal settings">×</button></div><div class="lesson-body"><p>Choose a daily XP target. A new lesson offers up to 45 XP including a combo bonus. Repeats earn up to 10 XP.</p><label for="daily-goal">Daily target</label><select id="daily-goal" style="display:block;padding:12px;margin:20px 0;width:100%;border:1px solid #dce5d7;border-radius:9px">${[20,30,50,80].map(n=>`<option value="${n}" ${state.goal===n?'selected':''}>${n} XP · ${n===20?'An easy start':n===30?'A steady habit':n===50?'A little extra':'A bigger challenge'}</option>`).join('')}</select><button class="primary" id="save-goal">Save my goal</button></div>`;$('#close-about').onclick=()=>$('#about-dialog').close();$('#save-goal').onclick=()=>{state.goal=Number($('#daily-goal').value);save();$('#about-dialog').close();render();toast('Your daily goal is saved.');};$('#about-dialog').showModal();}
let installPrompt=null;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
function about(){const d=$('#about-dialog');d.innerHTML=`<div class="dialog-head"><h3>Duolingo codex</h3><button class="close-btn" id="close-about" aria-label="Close about dialog" style="margin-left:auto">×</button></div><div class="lesson-body"><div class="eyebrow">BUSINESS · ONE SMALL WIN AT A TIME</div><p>An independent revision app for <strong>3rd-year Junior Cycle Business Studies in Ireland</strong>. Includes 24 lessons and 96 original questions across Personal Finance, Enterprise and Our Economy.</p><p>Use it alongside your teacher, textbook and examination practice. It introduces and revises selected concepts; it does not replace the complete course, extended accounts practice or classroom-based assessments.</p><p>Progress stays in this browser on this device. No account, tracking or cloud synchronisation. Clearing browser data clears progress.</p><div class="teach-note"><h3>Make it a standalone Chrome app</h3><p>${installPrompt?'Use the Install app button below.':'In Chrome, open the menu → Cast, save and share → Install page as app. The wording may vary by Chrome version. If installation is unavailable, bookmark this link.'} ${window.isSecureContext?'After the first visit, lessons can work offline.':'You’re using a local-network HTTP link. Keep this computer running and bookmark the page; offline installation needs HTTPS or localhost.'}</p></div><div class="about-links"><strong>Curriculum & reference sources</strong><br><a href="https://www.curriculumonline.ie/junior-cycle/junior-cycle-subjects/business-studies/expectations-for-students/" target="_blank" rel="noopener">NCCA · Junior Cycle learning outcomes ↗</a><br><a href="https://www.ccpc.ie/consumer-advice/faulty-products-and-goods/repairs-and-replacements/" target="_blank" rel="noopener">CCPC · Faulty goods guidance ↗</a><br><a href="https://www.revenue.ie/en/employing-people/what-constitutes-pay/what-are-gross-and-taxable-pay/index.aspx" target="_blank" rel="noopener">Revenue · Understanding gross pay ↗</a></div><p style="font-size:11px">Original teaching content. Calculations use illustrative figures, not live rates. Not affiliated with Duolingo or endorsed by NCCA. Reference guidance checked 26 October 2026.</p><div class="install-actions">${installPrompt?'<button class="primary" id="install-btn">Install app</button>':''}<button class="secondary" id="export-btn">Back up progress</button><label class="secondary" style="cursor:pointer">Restore backup<input type="file" accept="application/json,.json" id="import-file" hidden></label><button class="danger" id="reset-btn">Reset progress</button></div></div>`;$('#close-about').onclick=()=>d.close();if($('#install-btn'))$('#install-btn').onclick=async()=>{await installPrompt.prompt();installPrompt=null;};$('#export-btn').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='duolingo-codex-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Progress backup downloaded.');};$('#import-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>1000000)throw Error('File too large');const data=JSON.parse(await file.text());if(data.version!==1||!Number.isFinite(data.xp)||data.xp<0||!data.completed||!data.days||!Array.isArray(data.mistakes)||!Array.isArray(data.history)||![20,30,50,80].includes(data.goal))throw Error('Invalid backup');for(const [id,v] of Object.entries(data.completed)){if(!LESSONS.some(l=>l.id===id)||typeof v.passed!=='boolean'||!Number.isFinite(v.best)||v.best<0||v.best>100||!Number.isInteger(v.attempts)||v.attempts<0)throw Error('Invalid lesson');}for(const [date,v] of Object.entries(data.days)){if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!v||!Number.isFinite(v.xp)||v.xp<0||!Number.isInteger(v.sessions)||v.sessions<0)throw Error('Invalid day');}const ids=new Set(allQuestions().map(q=>q.id));if(data.mistakes.some(id=>!ids.has(id))||data.history.some(h=>typeof h.title!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(h.date)||!Number.isFinite(h.score)||h.score<0||h.score>100||!Number.isFinite(h.xp)||h.xp<0))throw Error('Invalid history');if(!STRANDS.some(s=>s.id===data.strand))data.strand='finance';pendingRestore=data;d.close();restoreConfirmation();}catch(err){toast('That file is not a valid progress backup.');}};$('#reset-btn').onclick=()=>{d.close();resetConfirmation();};d.showModal();}
let pendingRestore=null;
function restoreConfirmation(){const d=$('#about-dialog');d.innerHTML='<div class="lesson-body"><h2>Restore this progress backup?</h2><p>This will replace the progress currently saved in this browser.</p><div class="install-actions"><button class="secondary" id="cancel-restore">Keep current progress</button><button class="primary" id="confirm-restore">Restore backup</button></div></div>';$('#cancel-restore').onclick=()=>{pendingRestore=null;d.close();};$('#confirm-restore').onclick=()=>{state=pendingRestore;pendingRestore=null;save();d.close();render();toast('Your progress has been restored.');};d.showModal();}
function resetConfirmation(){const d=$('#about-dialog');d.innerHTML='<div class="lesson-body"><h2>Start fresh?</h2><p>This deletes XP, lesson results, streaks and saved mistakes from this browser. Export a backup first if you want to keep them.</p><div class="install-actions"><button class="secondary" id="cancel-reset">Keep my progress</button><button class="danger" id="confirm-reset">Delete my progress</button></div></div>';$('#cancel-reset').onclick=()=>{d.close();};$('#confirm-reset').onclick=()=>{state=blank();save();d.close();render();toast('Progress reset. A fresh start awaits.');};d.showModal();}
$('#about-btn').onclick=about;$('#mobile-about').onclick=about;$('#profile-btn').onclick=()=>{location.hash='progress';};window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});
